partial class Canvas {
 public void TestDraftPaint(){using(var b=new Bitmap(600,400))using(var g=Graphics.FromImage(b))OnPaint(new PaintEventArgs(g,new Rectangle(0,0,600,400)));}
 public void TestFrenchCurves(){Zoom=1;Offset=PointF.Empty;PressureMode="No pressure";Predictive=false;Tool="Pen";BrushSize=8;foreach(string name in new[]{"French curve · scroll","French curve · sweep","French curve · pear"}){SelectGuide(name);if(guidePoints.Length<100||StrokeSession.Distance(guidePoints[0],guidePoints.Last())>2)throw new Exception("Closed French template");EditGuide=true;PointF c=Centre();TestDrag(Point.Round(c),Point.Round(new PointF(c.X+10,c.Y+5)));if(StrokeSession.Distance(Centre(),new PointF(c.X+10,c.Y+5))>1)throw new Exception("Move French guide");EditGuide=false;using(var g=Graphics.FromImage(Doc.Selected.Image))g.Clear(Color.Transparent);int end=guidePoints.Length/8;TestDrag(Point.Round(guidePoints[0]),Point.Round(guidePoints[end]));var mid=guidePoints[end/2];if(Doc.Selected.Image.GetPixel((int)mid.X,(int)mid.Y).A==0)throw new Exception("Draw French guide");Tool="Eraser";BrushSize=20;TestDrag(Point.Round(guidePoints[0]),Point.Round(guidePoints[end]));if(Doc.Selected.Image.GetPixel((int)mid.X,(int)mid.Y).A!=0)throw new Exception("Erase French guide");Tool="Pen";BrushSize=8;}SelectGuide("Freehand");}
 public bool Predictive;public int Prediction=50;public float VectorTaper=30;
 public void ChangeVectorTaper(float amount){if(Doc!=null&&Doc.Selected.IsLocked)return;VectorTaper=amount;if(selectedVector==null||!selectedVector.CanTaper||selectedVector.Taper==amount)return;if(BeforeStroke!=null)BeforeStroke();selectedVector.Taper=amount;Doc.Selected.InvalidateVectors();if(AfterStroke!=null)AfterStroke();Invalidate();}
 void RebuildFrench(){
  PointF[] template=Guide.EndsWith("pear")?new[]{new PointF(-1,0),new PointF(-.7f,-.55f),new PointF(-.1f,-.65f),new PointF(.55f,-.28f),new PointF(1,0),new PointF(.55f,.28f),new PointF(-.1f,.65f),new PointF(-.7f,.55f)}:
   Guide.EndsWith("sweep")?new[]{new PointF(-1,.25f),new PointF(-.85f,-.35f),new PointF(-.35f,-.45f),new PointF(.2f,-.05f),new PointF(.7f,.15f),new PointF(1,-.2f),new PointF(.8f,.5f),new PointF(.25f,.4f),new PointF(-.35f,0),new PointF(-.7f,-.05f)}:
   new[]{new PointF(-1,0),new PointF(-.8f,-.5f),new PointF(-.25f,-.6f),new PointF(.2f,-.15f),new PointF(.6f,-.12f),new PointF(.7f,-.5f),new PointF(1,-.2f),new PointF(.85f,.25f),new PointF(.4f,.38f),new PointF(-.1f,.1f),new PointF(-.45f,.45f),new PointF(-.9f,.4f)};
  PointF c=Centre();float dx=(handles[1].X-handles[0].X)/2,dy=(handles[1].Y-handles[0].Y)/2;if(dx*dx+dy*dy<1)dx=1;
  for(int i=0;i<template.Length;i++){var t=template[i];template[i]=new PointF(c.X+t.X*dx-t.Y*dy,c.Y+t.X*dy+t.Y*dx);}
  using(var path=new GraphicsPath()){path.AddClosedCurve(template,.45f);path.Flatten(null,.3f);var pts=path.PathPoints;var dense=new List<PointF>();for(int i=0;i<pts.Length;i++){PointF a=pts[i],b=pts[(i+1)%pts.Length];int n=Math.Max(1,(int)Math.Ceiling(StrokeSession.Distance(a,b)));for(int j=0;j<n;j++)dense.Add(new PointF(a.X+(b.X-a.X)*j/n,a.Y+(b.Y-a.Y)*j/n));}guidePoints=dense.ToArray();}
 }
