partial class StrokeSession {
 public void Predict(int strength,float zoom){if(points.Count<3)return;var clean=PredictPoints(points,strength,zoom);float[] originalTravel=new float[points.Count];for(int i=1;i<points.Count;i++)originalTravel[i]=originalTravel[i-1]+Distance(points[i-1],points[i]);float cleanLength=0;for(int i=1;i<clean.Count;i++)cleanLength+=Distance(clean[i-1],clean[i]);
  // Retain pressure samples even when a nearly straight stroke collapses to a line.
  if(hardware&&clean.Count==2){var a=clean[0];var b=clean[1];clean.Clear();for(int i=0;i<originalTravel.Length;i++){float t=originalTravel[i]/Math.Max(.001f,originalTravel.Last());clean.Add(new PointF(a.X+(b.X-a.X)*t,a.Y+(b.Y-a.Y)*t));}}
  points.Clear();points.AddRange(clean);length=0;brush.Reset(points[0],size*(hardware?PressureScale(pressures[0]):pressure?TipScale:1));int sample=1;for(int i=1;i<points.Count;i++){length+=Distance(points[i-1],points[i]);float scale=pressure?TipScale+(1-TipScale)*Math.Min(1,length/TaperDistance):1;if(hardware){float at=length/Math.Max(.001f,cleanLength)*originalTravel.Last();while(sample<originalTravel.Length-1&&originalTravel[sample]<at)sample++;float t=Math.Max(0,Math.Min(1,(at-originalTravel[sample-1])/Math.Max(.001f,originalTravel[sample]-originalTravel[sample-1])));scale=PressureScale(pressures[sample-1]+(pressures[sample]-pressures[sample-1])*t);}brush.MoveSized(points[i],size*scale);}}
 public static List<PointF> PredictPoints(List<PointF> input,int strength,float zoom){var a=input[0];var b=input[input.Count-1];float chord=Distance(a,b),tolerance=(2+strength*.15f)/Math.Max(.02f,zoom);bool line=chord>tolerance*3;float lastProjection=-tolerance;foreach(var p in input){float projection=((p.X-a.X)*(b.X-a.X)+(p.Y-a.Y)*(b.Y-a.Y))/Math.Max(.001f,chord);if(Math.Abs((p.X-a.X)*(b.Y-a.Y)-(p.Y-a.Y)*(b.X-a.X))/Math.Max(.001f,chord)>tolerance||projection<lastProjection-tolerance||projection>chord+tolerance)line=false;lastProjection=projection;}if(line)return new List<PointF>{a,b};
  // Resample by distance so cleanup does not depend on mouse event rate.
  var samples=new List<PointF>{a};float spacing=Math.Max(.5f,2/Math.Max(.02f,zoom)),carry=0;
  for(int i=1;i<input.Count;i++){PointF from=input[i-1],to=input[i];float d=Distance(from,to);for(float at=spacing-carry;at<=d&&d>0;at+=spacing)samples.Add(new PointF(from.X+(to.X-from.X)*at/d,from.Y+(to.Y-from.Y)*at/d));carry=(carry+d)%spacing;}samples.Add(b);
  int radius=1+strength/15;for(int pass=0;pass<2;pass++){var next=new List<PointF>(samples);for(int i=1;i<samples.Count-1;i++){int r=Math.Min(radius,Math.Min(i,samples.Count-1-i));float x=0,y=0,total=0;for(int j=-r;j<=r;j++){float w=r+1-Math.Abs(j);x+=samples[i+j].X*w;y+=samples[i+j].Y*w;total+=w;}next[i]=new PointF(x/total,y/total);}samples=next;}return samples;
 }
}
partial class VectorShape {
 public bool CanTaper {get{return !Filled&&(Kind=="Line"||Kind=="Curvature pen"||Kind=="Polygon");}}
 public GraphicsPath TaperPath(){
  if(Kind=="Polygon"&&CornerRadius==0)return PolygonTaperPath();var outline=new GraphicsPath(FillMode.Winding);
  using(var path=Path()){
   if(path.PointCount<2)return outline;path.Flatten(null,.3f);var source=path.PathPoints;var pts=new List<PointF>{source[0]};
   for(int i=1;i<source.Length;i++){float d=StrokeSession.Distance(source[i-1],source[i]);int n=1;for(int j=1;j<=n;j++)pts.Add(new PointF(source[i-1].X+(source[i].X-source[i-1].X)*j/n,source[i-1].Y+(source[i].Y-source[i-1].Y)*j/n));}
   float[] lengths=new float[pts.Count],radii=new float[pts.Count];for(int i=1;i<pts.Count;i++)lengths[i]=lengths[i-1]+StrokeSession.Distance(pts[i-1],pts[i]);float total=lengths.Last(),taper=Math.Max(.01f,total*.5f*Taper/100);
   for(int i=0;i<pts.Count;i++)radii[i]=Width*.5f*(.03f+.97f*Math.Min(1,Math.Min(lengths[i],total-lengths[i])/taper));
   // Split only at taper transitions; width varies linearly between them.
   var refined=new List<PointF>{pts[0]};for(int i=1;i<pts.Count;i++){foreach(float at in new[]{taper,total-taper}.Distinct().OrderBy(v=>v))if(at>lengths[i-1]+.0001f&&at<lengths[i]-.0001f){float t=(at-lengths[i-1])/(lengths[i]-lengths[i-1]);refined.Add(new PointF(pts[i-1].X+(pts[i].X-pts[i-1].X)*t,pts[i-1].Y+(pts[i].Y-pts[i-1].Y)*t));}refined.Add(pts[i]);}pts=refined;
   lengths=new float[pts.Count];radii=new float[pts.Count];for(int i=1;i<pts.Count;i++)lengths[i]=lengths[i-1]+StrokeSession.Distance(pts[i-1],pts[i]);
   for(int i=0;i<pts.Count;i++)radii[i]=Width*.5f*(.03f+.97f*Math.Min(1,Math.Min(lengths[i],total-lengths[i])/taper));
   for(int i=0;i<pts.Count;i++){float radius=radii[i];
    if(i==0||i==pts.Count-1)outline.AddEllipse(pts[i].X-radius,pts[i].Y-radius,radius*2,radius*2);
    if(i==0)continue;var a=pts[i-1];var b=pts[i];float len=StrokeSession.Distance(a,b);if(len<.0001f)continue;float nx=-(b.Y-a.Y)/len,ny=(b.X-a.X)/len;
    outline.AddPolygon(new[]{new PointF(a.X-nx*radii[i-1],a.Y-ny*radii[i-1]),new PointF(b.X-nx*radius,b.Y-ny*radius),new PointF(b.X+nx*radius,b.Y+ny*radius),new PointF(a.X+nx*radii[i-1],a.Y+ny*radii[i-1])});
    if(i<pts.Count-1){var next=pts[i+1];double incoming=Math.Atan2(b.Y-a.Y,b.X-a.X),outgoing=Math.Atan2(next.Y-b.Y,next.X-b.X),turn=outgoing-incoming;while(turn>Math.PI)turn-=2*Math.PI;while(turn< -Math.PI)turn+=2*Math.PI;
     float sweep=(float)(Math.Abs(turn)*180/Math.PI);if(sweep>.001f){float start=(float)((turn>0?incoming-Math.PI/2:outgoing+Math.PI/2)*180/Math.PI);outline.AddPie(b.X-radius,b.Y-radius,radius*2,radius*2,start,sweep);}
    }
   }  }return outline;
 }
}
